import type { MainNavMenuProps, MainNavItemProps } from "../main-nav.types";

import React, { useRef, useEffect, useState } from "react";
import { Menu, MenuProps } from "@components/menu";
import { Accordion, AccordionProps, AccordionSectionProps } from "@components/accordion";
import { clsx } from "clsx";

import { MainNavItemParentContext, useMainNav } from "../hooks/use-main-nav";
import { MainNavClasses } from "../main-nav.styles";

import { MainNavItem } from "./main-nav-items";
import { MainNavUser } from "./main-nav-user";

export interface DisplayName {
  displayName?: string;
}

export const MainNavMenuRoot = ({
  disableAccordion = false,
  children,
  ...props
}: MainNavMenuProps) => {
  const { collapsed, theme } = useMainNav();
  const [menuOpen, setMenuOpen] = useState(false);

  const hasCurrentItem = (children: React.ReactNode): boolean => {
    return React.Children.toArray(children).some((child) => {
      if (!React.isValidElement(child)) {
        return false;
      }

      if (
        (child.type as DisplayName).displayName === MainNavItem.displayName &&
        child.props.isCurrent
      ) {
        return true;
      }

      if (child.props.children) {
        return hasCurrentItem(child.props.children);
      }

      return false;
    });
  };

  const content = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as DisplayName).displayName === MainNavMenuContent.displayName,
  );

  const isContentCurrent = content ? hasCurrentItem(content) : false;

  const mapToMenuChildren = (children: React.ReactNode): React.ReactNode => {
    return React.Children.map(children, (child) => {
      if (!React.isValidElement(child)) {
        return child;
      }

      const displayName = (child.type as DisplayName).displayName;

      switch (displayName) {
        case MainNavMenuTrigger.displayName: {
          const trigger = child.props.children;
          const triggerDisplayName = ((trigger as React.ReactElement).type as DisplayName)
            ?.displayName;
          const isNavItemTrigger =
            React.isValidElement(trigger) &&
            (triggerDisplayName === MainNavItem.displayName ||
              triggerDisplayName === MainNavUser.displayName);
          if (isNavItemTrigger) {
            const clonedTrigger = React.cloneElement(
              trigger as React.ReactElement<MainNavItemProps<"button">>,
              {
                disableTooltip:
                  menuOpen || (trigger.props as MainNavItemProps<"button">).disableTooltip,
              },
            );
            return (
              <Menu.Trigger
                {...child.props}
                data-main-nav-item-current={isContentCurrent || child.props.isCurrent}
              >
                {clonedTrigger}
              </Menu.Trigger>
            );
          }
          return <Menu.Trigger {...child.props}>{trigger}</Menu.Trigger>;
        }
        case MainNavMenuContent.displayName:
          return (
            <Menu.Content
              sideOffset={collapsed ? theme.toPx("0.86rem") : theme.toPx("1.14rem")}
              {...child.props}
            >
              {mapToMenuChildren(child.props.children)}
            </Menu.Content>
          );
        case MainNavMenuGroup.displayName:
          return (
            <Menu.Group {...child.props}>{mapToMenuChildren(child.props.children)}</Menu.Group>
          );
        case MainNavMenuLabel.displayName:
          return <Menu.Label {...child.props}>{child.props.children}</Menu.Label>;
        case MainNavItem.displayName:
          return (
            <Menu.Item asChild={true} data-main-nav-item-current={child.props.isCurrent}>
              {React.cloneElement(child, { ...child.props, disableTooltip: true })}
            </Menu.Item>
          );
        case MainNavMenuSub.displayName:
          return <Menu.Sub {...child.props}>{mapToMenuChildren(child.props.children)}</Menu.Sub>;
        case MainNavMenuSubTrigger.displayName: {
          const visualTriggerElement = child.props.children;
          if (
            React.isValidElement(visualTriggerElement) &&
            (visualTriggerElement.type as DisplayName)?.displayName === MainNavItem.displayName
          ) {
            const itemElement = visualTriggerElement as React.ReactElement<
              MainNavItemProps<"button">
            >;
            const { children: itemChildren, ...itemProps } = itemElement.props;
            return (
              <Menu.SubTrigger
                data-main-nav-item-current={isContentCurrent || child.props.isCurrent}
                {...child.props}
                {...itemProps}
              >
                {itemChildren}
              </Menu.SubTrigger>
            );
          }
          return (
            <Menu.SubTrigger {...child.props}>
              {mapToMenuChildren(visualTriggerElement)}
            </Menu.SubTrigger>
          );
        }
        case MainNavMenuSubContent.displayName:
          return (
            <Menu.SubContent sideOffset={theme.toPx("0.86rem")} {...child.props}>
              {mapToMenuChildren(child.props.children)}
            </Menu.SubContent>
          );
        default:
          return child;
      }
    });
  };

  const getTransformedChildrenForMenu = (children: React.ReactNode): React.ReactNode => {
    const transformedChildren = React.Children.map(children, (innerChildNode) => {
      if (React.isValidElement(innerChildNode) && innerChildNode.props.as === "button") {
        // Preserve MainNav.Item rendering (icons, hover swap, indicator) by cloning
        // and making it non-interactive for the Accordion header.
        return React.cloneElement(innerChildNode, {
          as: "div",
          className: clsx(MainNavClasses.item, innerChildNode.props.className),
          "data-main-nav-item-current": isContentCurrent || innerChildNode.props.isCurrent,
          disableTooltip: true,
          role: undefined,
          tabIndex: -1,
        });
      }
      return innerChildNode;
    });
    return transformedChildren;
  };

  const mapToAccordionChildren = (children: React.ReactNode): React.ReactNode => {
    return React.Children.map(children, (child) => {
      if (!React.isValidElement(child)) {
        return child;
      }

      const displayName = (child.type as DisplayName).displayName;

      switch (displayName) {
        case MainNavMenuTrigger.displayName:
          return (
            <Accordion.Header {...child.props}>
              {getTransformedChildrenForMenu(child.props.children)}
            </Accordion.Header>
          );
        case MainNavMenuContent.displayName:
          return (
            <Accordion.Content {...child.props}>
              {mapToAccordionChildren(child.props.children)}
            </Accordion.Content>
          );
        case MainNavMenuGroup.displayName:
          return React.Children.map(child.props.children, (groupChild) => {
            if (
              React.isValidElement(groupChild) &&
              (groupChild.type as DisplayName).displayName === MainNavMenuLabel.displayName
            ) {
              const typedGroupChild = groupChild as React.ReactElement;
              return <span>{typedGroupChild.props.children}</span>;
            }
            return groupChild;
          });
        case MainNavItem.displayName:
          return child;
        case MainNavMenuSub.displayName:
          return (
            <MainNavItemParentContext.Provider value="menu">
              <Menu {...(props as MenuProps)} alignOffset={theme.toPx("-0.286rem")} side="end">
                {mapToAccordionChildren(child.props.children)}
              </Menu>
            </MainNavItemParentContext.Provider>
          );
        case MainNavMenuSubTrigger.displayName:
          return <Menu.Trigger {...child.props}>{child.props.children}</Menu.Trigger>;
        case MainNavMenuSubContent.displayName:
          return (
            <Menu.Content sideOffset={theme.toPx("1.72rem")} {...child.props}>
              {mapToMenuChildren(child.props.children)}
            </Menu.Content>
          );
        default:
          return child;
      }
    });
  };

  const menuChildren = mapToMenuChildren(children);
  const accordionChildren = mapToAccordionChildren(children);

  if (collapsed || disableAccordion) {
    const menuProps = props as MenuProps;
    return (
      <MainNavItemParentContext.Provider value="menu">
        <Menu
          {...menuProps}
          alignOffset={theme.toPx("-0.286rem")}
          side="end"
          onOpenChange={(open) => {
            setMenuOpen(open);
            menuProps.onOpenChange?.(open);
          }}
        >
          {menuChildren}
        </Menu>
      </MainNavItemParentContext.Provider>
    );
  } else {
    return (
      <MainNavItemParentContext.Provider value="accordion">
        <Accordion {...(props as AccordionProps)}>
          <AccordionSectionWithScroll>{accordionChildren}</AccordionSectionWithScroll>
        </Accordion>
      </MainNavItemParentContext.Provider>
    );
  }
};
MainNavMenuRoot.displayName = "MainNav.Menu";

export const MainNavMenuTrigger: React.FC<React.PropsWithChildren> = ({ children }) => (
  <>{children}</>
);
MainNavMenuTrigger.displayName = "MainNav.MenuTrigger";

export const MainNavMenuContent: React.FC<React.PropsWithChildren> = ({ children }) => (
  <>{children}</>
);
MainNavMenuContent.displayName = "MainNav.MenuContent";

export const MainNavMenuGroup: React.FC<React.PropsWithChildren> = ({ children }) => (
  <>{children}</>
);
MainNavMenuGroup.displayName = "MainNav.MenuGroup";

export const MainNavMenuLabel: React.FC<React.PropsWithChildren> = ({ children }) => (
  <>{children}</>
);
MainNavMenuLabel.displayName = "MainNav.MenuLabel";

export const MainNavMenuSub: React.FC<React.PropsWithChildren> = ({ children }) => <>{children}</>;
MainNavMenuSub.displayName = "MainNav.MenuSub";

export const MainNavMenuSubTrigger: React.FC<React.PropsWithChildren> = ({ children }) => (
  <>{children}</>
);
MainNavMenuSubTrigger.displayName = "MainNav.MenuSubTrigger";

export const MainNavMenuSubContent: React.FC<React.PropsWithChildren> = ({ children }) => (
  <>{children}</>
);
MainNavMenuSubContent.displayName = "MainNav.MenuSubContent";

const AccordionSectionWithScroll = ({ children, ...props }: AccordionSectionProps) => {
  const sectionRef = useRef<HTMLDivElement>(null);
  const { contentRef } = useMainNav();

  useEffect(() => {
    const sectionElement = sectionRef.current;
    if (sectionElement) {
      const handleScroll = () => {
        sectionElement.scrollIntoView({ behavior: "smooth", block: "nearest" });
      };

      const observer = new MutationObserver(() => {
        const isExpanded = sectionElement.getAttribute("data-expanded") === "true";
        if (isExpanded) {
          if (sectionElement) {
            sectionElement.addEventListener("transitionend", handleScroll, { once: true });
          }
        }
      });

      observer.observe(sectionElement, {
        attributes: true,
        attributeFilter: ["data-expanded"],
      });

      return () => {
        observer.disconnect();
        if (sectionElement) {
          sectionElement.removeEventListener("transitionend", handleScroll);
        }
      };
    }
  }, [contentRef]);

  return (
    <Accordion.Section ref={sectionRef} {...props}>
      {children}
    </Accordion.Section>
  );
};

export const MainNavMenu = Object.assign(MainNavMenuRoot, {
  Trigger: MainNavMenuTrigger,
  Content: MainNavMenuContent,
  Group: MainNavMenuGroup,
  Label: MainNavMenuLabel,
  Sub: MainNavMenuSub,
  SubTrigger: MainNavMenuSubTrigger,
  SubContent: MainNavMenuSubContent,
});
